"""The web API: a small JSON-over-HTTP server on the same book file as the command line.

Design notes
------------
* ``http.server`` is used only for sockets and threads; request lines, answers and
  every error are handled here so that nothing is ever printed and every answer has
  a ``Content-Length`` and ``Connection: close``.
* Every request runs in its own thread and opens (and closes) the book for itself.
* Checks are made in the documented order: path (404), verb (405), body length
  (400/413), body type (415), body is JSON (400), then the book and the library.
* The body of a request that is answered before it was read is drained, so the
  client always gets its answer (and not a connection reset).
"""
import json
import os
import re
import signal
import socket
import socketserver
import sys
import threading
from datetime import date
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qsl, unquote

from tallybook import __version__
from tallybook.budgets import Budget, budget_status
from tallybook.dates import Period, format_date, parse_date
from tallybook.errors import (ConflictError, NotFoundError, ParseError, TallybookError,
                              ValidationError)
from tallybook.export import money_to_dict, to_json, transaction_to_dict, transactions_to_csv
from tallybook.journal import format_journal
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.recurring import Recurring
from tallybook.reports import (balance_sheet, cashflow, income_statement, register,
                               render_text, trial_balance)
from tallybook.storage import LATEST_VERSION, Store

MAX_BODY = 1048576
MAX_DRAIN = 1 << 29
INT64_MAX = 9223372036854775807
JSON_TYPES = ("application/json",)
CSV_TYPES = ("application/json", "text/csv", "text/plain")

_DIGITS = re.compile(r"[0-9]+")
_STATUS_OF_CODE = {"parse": 400, "validation": 400, "not_found": 404, "conflict": 409}


# ---------------------------------------------------------------------------
# answers
# ---------------------------------------------------------------------------
class HttpError(Exception):
    """An answer decided by the API itself (not by the library)."""

    def __init__(self, status, message, headers=()):
        Exception.__init__(self, message)
        self.status = status
        self.message = message
        self.headers = list(headers)


class Text:
    """A plain text answer."""

    def __init__(self, text, content_type="text/plain; charset=utf-8", status=200):
        self.text = text
        self.content_type = content_type
        self.status = status


def _message(exc):
    text = getattr(exc, "message", None) or str(exc)
    return text if text else (getattr(exc, "code", None) or "error")


# ---------------------------------------------------------------------------
# reading the request
# ---------------------------------------------------------------------------
def _whole(text, what):
    if not _DIGITS.fullmatch(text) or int(text) > INT64_MAX:
        raise ValidationError("%s must be a whole number from 0 to %d" % (what, INT64_MAX))
    return int(text)


def _yes_no(text, what):
    low = text.lower() if text.isascii() else ""
    if low in ("true", "yes", "1"):
        return True
    if low in ("false", "no", "0"):
        return False
    raise ValidationError("%s must be yes or no, not '%s'" % (what, text))


def _no_constant(name):
    raise ValueError("invalid JSON constant %s" % name)


def _decode_json(raw):
    """The JSON value of a request body (an empty body is {})."""
    if raw == b"":
        return {}
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise ParseError("the body is not valid UTF-8")
    try:
        value = json.loads(text, parse_constant=_no_constant)
    except RecursionError:
        raise ParseError("the body is not valid JSON: nested too deeply")
    except ValueError as exc:
        raise ParseError("the body is not valid JSON: %s" % exc)
    try:
        json.dumps(value, ensure_ascii=False).encode("utf-8")
    except UnicodeEncodeError:
        raise ParseError("the body is not valid JSON: it holds an unpaired surrogate")
    except RecursionError:
        raise ParseError("the body is not valid JSON: nested too deeply")
    if not isinstance(value, dict):
        raise ValidationError("the body must be a JSON object")
    return value


class Request:
    """What a route function sees: path pieces, query, body, today, the book."""

    def __init__(self, server, method, pieces, query, raw_body, content_type):
        self.server = server
        self.method = method
        self.pieces = pieces
        self.query = query
        self.raw_body = raw_body
        self.content_type = content_type
        self._json = None

    @property
    def today(self):
        return self.server.today if self.server.today is not None else date.today()

    @property
    def body(self):
        if self._json is None:
            self._json = _decode_json(self.raw_body)
        return self._json

    def store(self):
        return Store.open(self.server.db_path)

    # -- query string ----------------------------------------------------
    def q(self, name, required=False):
        if name in self.query:
            return self.query[name]
        if required:
            raise ValidationError("missing query parameter: %s" % name)
        return None

    def q_date(self, name, required=False):
        v = self.q(name, required)
        return None if v is None else parse_date(v)

    def q_period(self, name, required=False):
        v = self.q(name, required)
        return None if v is None else Period.parse(v)

    def q_bool(self, name, default):
        v = self.q(name)
        return default if v is None else _yes_no(v, "parameter %s" % name)

    def q_whole(self, name, default=None):
        v = self.q(name)
        return default if v is None else _whole(v, "parameter %s" % name)

    def q_choice(self, name, choices, default):
        v = self.q(name)
        if v is None:
            return default
        if v not in choices:
            raise ValidationError("parameter %s must be one of: %s" % (name, ", ".join(choices)))
        return v


# -- body fields ---------------------------------------------------------------
def check_fields(obj, required=(), optional=()):
    allowed = set(required) | set(optional)
    for key in sorted(obj):
        if key not in allowed:
            raise ValidationError("unknown field: %s" % key)
    for key in required:
        if obj.get(key) is None:
            raise ValidationError("missing field: %s" % key)


def f_text(obj, name, default=None):
    v = obj.get(name)
    if v is None:
        return default
    if not isinstance(v, str):
        raise ValidationError("field %s must be text" % name)
    return v


def f_date(obj, name, default=None):
    v = f_text(obj, name)
    return default if v is None else parse_date(v)


def f_list(obj, name, default=None):
    v = obj.get(name)
    if v is None:
        return default
    if not isinstance(v, list):
        raise ValidationError("field %s must be a list" % name)
    return v


def f_object(obj, name):
    v = obj.get(name)
    if v is None:
        return None
    if not isinstance(v, dict):
        raise ValidationError("field %s must be an object" % name)
    return v


def read_money(value, what="amount"):
    if isinstance(value, str):
        return Money.parse(value)
    if isinstance(value, dict):
        if set(value) != {"amount", "currency"}:
            raise ValidationError("%s must have exactly the fields amount and currency" % what)
        if not isinstance(value["amount"], str) or not isinstance(value["currency"], str):
            raise ValidationError("%s: amount and currency must be text" % what)
        return Money.of(value["amount"], value["currency"])
    raise ValidationError("%s must be an object with amount and currency, or text like '12.50 USD'" % what)


def read_postings(items):
    out = []
    for item in items:
        if not isinstance(item, dict):
            raise ValidationError("a posting must be an object")
        check_fields(item, ["account"], ["amount", "note"])
        account = f_text(item, "account")
        note = f_text(item, "note", "")
        raw = item.get("amount")
        out.append(Posting(account, None if raw is None else read_money(raw), note))
    return out


def read_transaction(obj, with_date):
    check_fields(obj, ["date", "payee", "postings"] if with_date else ["payee", "postings"],
                 ["narration", "flag", "tags"])
    day = f_date(obj, "date") if with_date else None
    payee = f_text(obj, "payee")
    narration = f_text(obj, "narration", "")
    flag = f_text(obj, "flag", "*")
    tags = f_list(obj, "tags", [])
    if not all(isinstance(t, str) for t in tags):
        raise ValidationError("field tags must be a list of text")
    postings = read_postings(f_list(obj, "postings"))
    return Transaction(day, payee, narration, postings, tuple(tags), flag, None)


# -- output shapes ---------------------------------------------------------------
def account_to_dict(a):
    return {"path": a.path, "type": a.type, "currency": a.currency,
            "opened": None if a.opened is None else format_date(a.opened),
            "closed": None if a.closed is None else format_date(a.closed), "note": a.note}


def rate_to_dict(row):
    src, dst, on, text = row
    return {"src": src, "dst": dst, "date": format_date(on), "rate": text}


def budget_to_dict(b):
    return {"pattern": b.pattern, "period_kind": b.period_kind,
            "amount": money_to_dict(b.amount), "start": format_date(b.start)}


def recurring_to_dict(rec):
    t = rec.template
    return {
        "name": rec.name, "schedule": str(rec.schedule), "start": format_date(rec.start),
        "end": None if rec.end is None else format_date(rec.end), "count": rec.count,
        "template": {
            "payee": t.payee, "narration": t.narration, "flag": t.flag, "tags": sorted(set(t.tags)),
            "postings": [{"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
                         for p in t.postings],
        },
    }


# ---------------------------------------------------------------------------
# the routes
# ---------------------------------------------------------------------------
def h_health(r):
    with r.store() as store:
        return 200, {"status": "ok", "version": __version__, "schema_version": store.version}


def h_accounts_list(r):
    kind, under, cur = r.q("type"), r.q("under"), r.q("currency")
    include_closed = r.q_bool("include_closed", True)
    with r.store() as store:
        return 200, [account_to_dict(a) for a in store.accounts(kind, under, cur, include_closed)]


def h_accounts_add(r):
    b = r.body
    check_fields(b, ["path"], ["type", "currency", "opened", "note"])
    path, kind, cur = f_text(b, "path"), f_text(b, "type"), f_text(b, "currency")
    opened, note = f_date(b, "opened"), f_text(b, "note", "")
    with r.store() as store:
        return 201, account_to_dict(store.add_account(path, kind, cur, opened, note))


def h_account_get(r):
    with r.store() as store:
        return 200, account_to_dict(store.get_account(r.pieces[1]))


def h_account_close(r):
    b = r.body
    check_fields(b, [], ["on"])
    on = f_date(b, "on", r.today)
    with r.store() as store:
        return 200, account_to_dict(store.close_account(r.pieces[1], on))


def h_tx_list(r):
    q = r.q("q")
    limit, offset = r.q_whole("limit"), r.q_whole("offset", 0)
    with r.store() as store:
        found = store.transactions(q)
    page = found[offset:] if limit is None else found[offset:offset + limit]
    return 200, {"items": [transaction_to_dict(t) for t in page], "total": len(found),
                 "limit": limit, "offset": offset}


def h_tx_add(r):
    tx = read_transaction(r.body, True)
    with r.store() as store:
        return 201, transaction_to_dict(store.add_transaction(tx))


def h_tx_get(r):
    with r.store() as store:
        return 200, transaction_to_dict(store.get_transaction(int(r.pieces[1])))


def h_tx_delete(r):
    with r.store() as store:
        return 200, transaction_to_dict(store.delete_transaction(int(r.pieces[1])))


def h_rates_list(r):
    with r.store() as store:
        return 200, [rate_to_dict(row) for row in store.rate_rows()]


def h_rates_put(r):
    b = r.body
    check_fields(b, ["src", "dst", "date", "rate"])
    src, dst, rate = f_text(b, "src"), f_text(b, "dst"), f_text(b, "rate")
    on = f_date(b, "date")
    with r.store() as store:
        store.set_rate(src, dst, rate, on)
        return 200, {"src": src, "dst": dst, "date": format_date(on), "rate": rate}


def h_rates_delete(r):
    src, dst = r.q("src", True), r.q("dst", True)
    on = r.q_date("date", True)
    with r.store() as store:
        found = [row for row in store.rate_rows() if row[0] == src and row[1] == dst and row[2] == on]
        store.remove_rate(src, dst, on)
        return 200, rate_to_dict(found[0]) if found else {"src": src, "dst": dst, "date": format_date(on)}


def h_budgets_list(r):
    with r.store() as store:
        return 200, [budget_to_dict(b) for b in store.budgets()]


def h_budgets_add(r):
    b = r.body
    check_fields(b, ["pattern", "period_kind", "amount", "start"])
    budget = Budget(f_text(b, "pattern"), f_text(b, "period_kind"), read_money(b["amount"]),
                    f_date(b, "start"))
    with r.store() as store:
        store.add_budget(budget)
    return 201, budget_to_dict(budget)


def h_budgets_delete(r):
    pattern, kind = r.q("pattern", True), r.q("period_kind", True)
    with r.store() as store:
        found = [b for b in store.budgets() if b.pattern == pattern and b.period_kind == kind]
        store.remove_budget(pattern, kind)
        return 200, budget_to_dict(found[0])


def h_budgets_status(r):
    period = r.q_period("period", True)
    with r.store() as store:
        budgets = store.budgets()
        ledger = store.ledger()
    return 200, [line.to_dict() for line in budget_status(budgets, ledger, period)]


def h_recurring_list(r):
    with r.store() as store:
        return 200, [recurring_to_dict(rec) for rec in store.recurring()]


def h_recurring_add(r):
    b = r.body
    check_fields(b, ["name", "schedule", "start", "template"], ["end", "count"])
    template = read_transaction(f_object(b, "template"), False)
    template = Transaction(None, template.payee, template.narration, template.postings,
                           tuple(sorted(set(template.tags))), template.flag, None)
    rec = Recurring(b["name"], b["schedule"], template, f_date(b, "start"), f_date(b, "end"),
                    b.get("count"))
    with r.store() as store:
        store.add_recurring(rec)
    return 201, recurring_to_dict(rec)


def h_recurring_delete(r):
    name = r.q("name", True)
    with r.store() as store:
        found = [rec for rec in store.recurring() if rec.name == name]
        store.remove_recurring(name)
        return 200, recurring_to_dict(found[0])


def h_materialize(r):
    b = r.body
    check_fields(b, [], ["upto"])
    upto = f_date(b, "upto")
    with r.store() as store:
        added = store.materialize(upto, r.today)
    return 200, {"added": [transaction_to_dict(t) for t in added]}


def _report(r, name):
    fmt = r.q_choice("format", ("json", "text"), "json")
    convert = r.q("convert_to")
    if name == "trial-balance":
        as_of = r.q_date("as_of")
        make = lambda led: trial_balance(led, as_of)
    elif name == "balance-sheet":
        as_of = r.q_date("as_of")
        make = lambda led: balance_sheet(led, as_of, convert, r.today)
    elif name == "income-statement":
        period = r.q_period("period", True)
        make = lambda led: income_statement(led, period, convert)
    elif name == "cashflow":
        period = r.q_period("period", True)
        make = lambda led: cashflow(led, period)
    else:
        account = r.q("account", True)
        period = r.q_period("period")
        rollup = r.q_bool("rollup", False)
        make = lambda led: register(led, account, period, rollup)
    with r.store() as store:
        ledger = store.ledger()
    report = make(ledger)
    if fmt == "text":
        return Text(render_text(report))
    return 200, report


def h_import(r):
    ctype = r.content_type
    if ctype == "application/json":
        b = r.body
        check_fields(b, ["csv", "profile"], ["apply_rules"])
        text, profile = f_text(b, "csv"), f_text(b, "profile")
        rules = b.get("apply_rules")
        if rules is None:
            rules = True
        elif not isinstance(rules, bool):
            raise ValidationError("field apply_rules must be true or false")
    else:
        profile = r.q("profile", True)
        rules = r.q_bool("apply_rules", True)
        try:
            text = r.raw_body.decode("utf-8")
        except UnicodeDecodeError:
            raise ParseError("the body is not valid UTF-8")
    with r.store() as store:
        outcome = store.import_csv(text, profile, rules)
    if outcome.errors:
        raise ValidationError("import failed: " + "; ".join("row %d: %s" % (n, m) for n, m in outcome.errors))
    return 200, {"added": [transaction_to_dict(t) for t in outcome.added],
                 "duplicates": [transaction_to_dict(t) for t in outcome.duplicates]}


def h_rules_get(r):
    with r.store() as store:
        return 200, {"rules": store.rules_text()}


def h_rules_put(r):
    b = r.body
    check_fields(b, ["rules"])
    text = f_text(b, "rules")
    with r.store() as store:
        store.set_rules(text)
        return 200, {"rules": store.rules_text()}


def h_export(r):
    fmt = r.q_choice("format", ("json", "csv", "journal"), "json")
    with r.store() as store:
        if fmt == "journal":
            return Text(format_journal(store.journal()))
        txs = store.transactions()
    if fmt == "csv":
        return Text(transactions_to_csv(txs), "text/csv; charset=utf-8")
    return 200, [transaction_to_dict(t) for t in txs]


REPORT_NAMES = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


def resolve(pieces):
    """The (verbs -> function, accepted body types) of a path, or None for an unknown path."""
    n = len(pieces)
    if n == 0 or any(p == "" for p in pieces):
        return None
    head = pieces[0]
    if head == "health" and n == 1:
        return {"GET": h_health}
    if head == "accounts":
        if n == 1:
            return {"GET": h_accounts_list, "POST": h_accounts_add}
        if n == 2:
            return {"GET": h_account_get}
        if n == 3 and pieces[2] == "close":
            return {"POST": h_account_close}
        return None
    if head == "transactions":
        if n == 1:
            return {"GET": h_tx_list, "POST": h_tx_add}
        if n == 2 and _DIGITS.fullmatch(pieces[1]):
            return {"GET": h_tx_get, "DELETE": h_tx_delete}
        return None
    if head == "rates" and n == 1:
        return {"GET": h_rates_list, "PUT": h_rates_put, "DELETE": h_rates_delete}
    if head == "budgets":
        if n == 1:
            return {"GET": h_budgets_list, "POST": h_budgets_add, "DELETE": h_budgets_delete}
        if n == 2 and pieces[1] == "status":
            return {"GET": h_budgets_status}
        return None
    if head == "recurring":
        if n == 1:
            return {"GET": h_recurring_list, "POST": h_recurring_add, "DELETE": h_recurring_delete}
        if n == 2 and pieces[1] == "materialize":
            return {"POST": h_materialize}
        return None
    if head == "reports" and n == 2 and pieces[1] in REPORT_NAMES:
        name = pieces[1]
        return {"GET": lambda r: _report(r, name)}
    if head == "import" and n == 1:
        return {"POST": h_import}
    if head == "rules" and n == 1:
        return {"GET": h_rules_get, "PUT": h_rules_put}
    if head == "export" and n == 1:
        return {"GET": h_export}
    return None


def _accepted_types(pieces):
    return CSV_TYPES if pieces[0] == "import" else JSON_TYPES


# ---------------------------------------------------------------------------
# the HTTP layer
# ---------------------------------------------------------------------------
def _json_bytes(obj):
    return to_json(obj).encode("utf-8", "replace")


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    timeout = 30

    # nothing is ever logged
    def log_message(self, format, *args):
        pass

    def log_request(self, code="-", size="-"):
        pass

    def log_error(self, format, *args):
        pass

    def send_error(self, code, message=None, explain=None):
        """Called by the base class parser for a request it cannot read: always a 400."""
        self._answer(400, "application/json; charset=utf-8",
                     _json_bytes({"error": "bad request: %s" % (message or "unreadable request")}))

    # -- one request ---------------------------------------------------------
    def handle(self):
        self.close_connection = True
        self._body_left = 0
        try:
            self._one()
        except (OSError, ValueError):
            pass  # the client went away, or timed out: nothing to say, nobody to tell

    def _one(self):
        line = self.rfile.readline(65537)
        self.raw_requestline = line
        if not line:
            return
        if len(line) > 65536:
            self.command = None
            self.send_error(400, "request line too long")
            self._linger()
            return
        if not self.parse_request():
            self._linger()
            return
        self.close_connection = True
        if self.request_version == "HTTP/0.9":
            self.send_error(400, "missing HTTP version")
            return
        self._request()

    def _answer(self, status, ctype, body, extra=()):
        if getattr(self, "command", None) == "HEAD":
            body = b""  # an answer to HEAD has no body, and says so
        lines = ["HTTP/1.1 %d %s" % (status, HTTPStatus(status).phrase),
                 "Content-Type: " + ctype,
                 "Content-Length: %d" % len(body),
                 "Connection: close"]
        lines.extend(extra)
        data = ("\r\n".join(lines) + "\r\n\r\n").encode("latin-1") + body
        self.wfile.write(data)
        self.wfile.flush()

    def _linger(self):
        """After an answer to a request we did not read: let the client finish sending."""
        try:
            self.connection.shutdown(socket.SHUT_WR)
            self.connection.settimeout(0.5)
            total = 0
            while total < (4 << 20):
                chunk = self.connection.recv(65536)
                if not chunk:
                    break
                total += len(chunk)
        except OSError:
            pass

    def _drain(self):
        left, cap = self._body_left, MAX_DRAIN
        while left > 0 and cap > 0:
            chunk = self.rfile.read(min(left, 65536))
            if not chunk:
                break
            left -= len(chunk)
            cap -= len(chunk)
        self._body_left = 0

    def _target(self):
        words = self.raw_requestline.decode("iso-8859-1").rstrip("\r\n").split()
        raw = words[1].encode("iso-8859-1").decode("utf-8", "replace")
        raw = raw.split("#", 1)[0]
        path, _, qs = raw.partition("?")
        return path, qs

    def _request(self):
        method = self.command
        status, ctype, body, extra = 200, "application/json; charset=utf-8", b"", ()
        try:
            result = self._process(method)
            if isinstance(result, Text):
                status, ctype = result.status, result.content_type
                body = result.text.encode("utf-8", "replace")
            else:
                status, obj = result
                body = _json_bytes(obj)
        except HttpError as exc:
            status, body, extra = exc.status, _json_bytes({"error": exc.message}), exc.headers
        except TallybookError as exc:
            status = _STATUS_OF_CODE.get(exc.code, 400)
            body = _json_bytes({"error": _message(exc)})
        except RecursionError:
            status, body = 400, _json_bytes({"error": "the request is nested too deeply"})
        except MemoryError:
            status, body = 500, _json_bytes({"error": "out of memory"})
        except Exception as exc:  # a bug must never print a traceback
            status = 500
            body = _json_bytes({"error": "internal error: %s" % type(exc).__name__})
        self._answer(status, ctype, body, extra)
        self._drain()

    def _process(self, method):
        path, qs = self._target()
        if not path.startswith("/"):
            raise HttpError(404, "no such path: %s" % path)
        pieces = [unquote(p, errors="replace") for p in path[1:].split("/")]
        routes = resolve(pieces)
        length_text = self.headers.get("Content-Length")
        declared = None
        if length_text is not None and _DIGITS.fullmatch(length_text) and length_text.isascii():
            declared = int(length_text)
            self._body_left = declared
        if routes is None:
            raise HttpError(404, "no such path: %s" % path)
        handler = routes.get(method)
        if handler is None:
            allow = ", ".join(sorted(routes))
            raise HttpError(405, "method %s is not allowed here; use %s" % (method, allow),
                            ["Allow: " + allow])
        # the body: length, then type
        if length_text is None:
            declared = 0
        if declared is None:
            raise HttpError(400, "Content-Length must be a whole number")
        if self.headers.get("Transfer-Encoding") is not None:
            raise HttpError(400, "Transfer-Encoding is not supported; send a Content-Length")
        if declared > MAX_BODY:
            raise HttpError(413, "the body is larger than %d bytes" % MAX_BODY)
        raw = self.rfile.read(declared) if declared else b""
        self._body_left = 0
        if len(raw) < declared:
            raise HttpError(400, "the body is shorter than its Content-Length")
        ctype = (self.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
        if method in ("POST", "PUT") and raw and ctype not in _accepted_types(pieces):
            raise HttpError(415, "unsupported Content-Type %r; use %s"
                            % (ctype, " or ".join(_accepted_types(pieces))))
        query = {}
        if qs:
            for name, value in parse_qsl(qs, keep_blank_values=True, errors="replace"):
                query[name] = value
        if method in ("GET", "DELETE"):
            raw = b""
        req = Request(self.server, method, pieces, query, raw, ctype)
        return handler(req)


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    block_on_close = False
    request_queue_size = 128

    def server_bind(self):
        socketserver.TCPServer.server_bind(self)
        host, port = self.server_address[:2]
        self.server_name = str(host)
        self.server_port = port

    def handle_error(self, request, client_address):
        pass  # a dropped connection or a bug in one request never reaches the terminal


class _Server6(_Server):
    address_family = socket.AF_INET6


# ---------------------------------------------------------------------------
# starting
# ---------------------------------------------------------------------------
def check_book(db_path):
    """Open the book once and check it as every command does."""
    with Store.open(db_path) as store:
        version = store.version
        if version < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % version)


def make_server(db_path, host="127.0.0.1", port=0, today=None):
    """A bound (not yet serving) server; ``serve_forever`` / ``shutdown`` / ``server_close`` as usual."""
    check_book(db_path)
    full = os.path.abspath(os.fspath(db_path))
    cls = _Server6 if ":" in host else _Server
    try:
        server = cls((host, port), Handler)
    except OverflowError:
        raise ValidationError("invalid port: %s" % (port,))
    except OSError as exc:
        raise ConflictError("cannot listen on %s:%s: %s" % (host, port, exc.strerror or exc))
    server.db_path = full
    server.today = today
    return server


def serve(db_path, host="127.0.0.1", port=0, today=None, *, _started=None):
    """Serve the book until SIGINT or SIGTERM; returns 0.

    ``_started(server)`` (for tests) is called once the listening line is printed.
    """
    server = make_server(db_path, host, port, today)
    previous = {}
    try:
        if threading.current_thread() is threading.main_thread():
            def stop(signum, frame):
                threading.Thread(target=server.shutdown, daemon=True).start()
            for sig in (signal.SIGINT, signal.SIGTERM):
                previous[sig] = signal.signal(sig, stop)
        shown = "[%s]" % host if ":" in host else host
        try:
            sys.stdout.write("tallybook listening on http://%s:%d\n" % (shown, server.server_address[1]))
            sys.stdout.flush()
        except (OSError, ValueError):
            pass
        if _started is not None:
            _started(server)
        try:
            server.serve_forever(poll_interval=0.1)
        except KeyboardInterrupt:
            pass
    finally:
        server.server_close()
        for sig, old in previous.items():
            signal.signal(sig, old)
    return 0
