def _message(exc):
    text = getattr(exc, "message", None) or str(exc)
    return text if text else (getattr(exc, "code", None) or "error")


# ---------------------------------------------------------------------------
# reading the request
# ---------------------------------------------------------------------------
def _whole(text, what):
    if not _DIGITS.fullmatch(text) or int(text) > INT64_MAX:
        raise ValidationError("%s must be a whole number from 0 to %d" % (what, INT64_MAX))
    return int(text)


def _yes_no(text, what):
    low = text.lower() if text.isascii() else ""
    if low in ("true", "yes", "1"):
        return True
    if low in ("false", "no", "0"):
        return False
    raise ValidationError("%s must be yes or no, not '%s'" % (what, text))


def _no_constant(name):
    raise ValueError("invalid JSON constant %s" % name)


def _decode_json(raw):
    """The JSON value of a request body (an empty body is {})."""
    if raw == b"":
        return {}
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise ParseError("the body is not valid UTF-8")
    try:
        value = json.loads(text, parse_constant=_no_constant)
    except RecursionError:
        raise ParseError("the body is not valid JSON: nested too deeply")
    except ValueError as exc:
        raise ParseError("the body is not valid JSON: %s" % exc)
    try:
        json.dumps(value, ensure_ascii=False).encode("utf-8")
    except UnicodeEncodeError:
        raise ParseError("the body is not valid JSON: it holds an unpaired surrogate")
    except RecursionError:
        raise ParseError("the body is not valid JSON: nested too deeply")
    if not isinstance(value, dict):
        raise ValidationError("the body must be a JSON object")
    return value


class Request:
    """What a route function sees: path pieces, query, body, today, the book."""

    def __init__(self, server, method, pieces, query, raw_body, content_type):
        self.server = server
        self.method = method
        self.pieces = pieces
        self.query = query
        self.raw_body = raw_body
        self.content_type = content_type
        self._json = None

    @property
    def today(self):
        return self.server.today if self.server.today is not None else date.today()

    @property
    def body(self):
        if self._json is None:
            self._json = _decode_json(self.raw_body)
        return self._json

    def store(self):
        return Store.open(self.server.db_path)

    # -- query string ----------------------------------------------------
    def q(self, name, required=False):
        if name in self.query:
            return self.query[name]
        if required:
            raise ValidationError("missing query parameter: %s" % name)
        return None

    def q_date(self, name, required=False):
        v = self.q(name, required)
        return None if v is None else parse_date(v)

    def q_period(self, name, required=False):
        v = self.q(name, required)
        return None if v is None else Period.parse(v)

    def q_bool(self, name, default):
        v = self.q(name)
        return default if v is None else _yes_no(v, "parameter %s" % name)

    def q_whole(self, name, default=None):
        v = self.q(name)
        return default if v is None else _whole(v, "parameter %s" % name)

    def q_choice(self, name, choices, default):
        v = self.q(name)
        if v is None:
            return default
        if v not in choices:
            raise ValidationError("parameter %s must be one of: %s" % (name, ", ".join(choices)))
        return v


