    if isinstance(value, dict):
        if set(value) != {"amount", "currency"}:
            raise ValidationError("%s must have exactly the fields amount and currency" % what)
        if not isinstance(value["amount"], str) or not isinstance(value["currency"], str):
            raise ValidationError("%s: amount and currency must be text" % what)
        return Money.of(value["amount"], value["currency"])
    raise ValidationError("%s must be an object with amount and currency, or text like '12.50 USD'" % what)


