        check_fields(item, ["account"], ["amount", "note"])
        account = f_text(item, "account")
        note = f_text(item, "note", "")
        raw = item.get("amount")
        out.append(Posting(account, None if raw is None else read_money(raw), note))
    return out


def read_transaction(obj, with_date):
    check_fields(obj, ["date", "payee", "postings"] if with_date else ["payee", "postings"],
                 ["narration", "flag", "tags"])
    day = f_date(obj, "date") if with_date else None
