    if head == "accounts":
        if n == 1:
            return {"GET": h_accounts_list, "POST": h_accounts_add}
        if n == 2:
            return {"GET": h_account_get}
        if n == 3 and pieces[2] == "close":
            return {"POST": h_account_close}
        return None
    if head == "transactions":
        if n == 1:
            return {"GET": h_tx_list, "POST": h_tx_add}
        if n == 2 and _DIGITS.fullmatch(pieces[1]):
            return {"GET": h_tx_get, "DELETE": h_tx_delete}
        return None
    if head == "rates" and n == 1:
        return {"GET": h_rates_list, "PUT": h_rates_put, "DELETE": h_rates_delete}
    if head == "budgets":
        if n == 1:
            return {"GET": h_budgets_list, "POST": h_budgets_add, "DELETE": h_budgets_delete}
        if n == 2 and pieces[1] == "status":
            return {"GET": h_budgets_status}
        return None
    if head == "recurring":
        if n == 1:
            return {"GET": h_recurring_list, "POST": h_recurring_add, "DELETE": h_recurring_delete}
        if n == 2 and pieces[1] == "materialize":
            return {"POST": h_materialize}
        return None
    if head == "reports" and n == 2 and pieces[1] in REPORT_NAMES:
        name = pieces[1]
        return {"GET": lambda r: _report(r, name)}
    if head == "import" and n == 1:
        return {"POST": h_import}
    if head == "rules" and n == 1:
        return {"GET": h_rules_get, "PUT": h_rules_put}
    if head == "export" and n == 1:
        return {"GET": h_export}
    return None


def _accepted_types(pieces):
    return CSV_TYPES if pieces[0] == "import" else JSON_TYPES


# ---------------------------------------------------------------------------
# the HTTP layer
# ---------------------------------------------------------------------------
def _json_bytes(obj):
    return to_json(obj).encode("utf-8", "replace")


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    timeout = 30

    # nothing is ever logged
    def log_message(self, format, *args):
        pass

    def log_request(self, code="-", size="-"):
        pass

    def log_error(self, format, *args):
        pass

    def send_error(self, code, message=None, explain=None):
        """Called by the base class parser for a request it cannot read: always a 400."""
        self._answer(400, "application/json; charset=utf-8",
                     _json_bytes({"error": "bad request: %s" % (message or "unreadable request")}))

    # -- one request ---------------------------------------------------------
    def handle(self):
        self.close_connection = True
        self._body_left = 0
        try:
            self._one()
        except (OSError, ValueError):
            pass  # the client went away, or timed out: nothing to say, nobody to tell

    def _one(self):
        line = self.rfile.readline(65537)
        self.raw_requestline = line
        if not line:
            return
        if len(line) > 65536:
            self.command = None
            self.send_error(400, "request line too long")
            self._linger()
            return
        if not self.parse_request():
            self._linger()
            return
        self.close_connection = True
        if self.request_version == "HTTP/0.9":
            self.send_error(400, "missing HTTP version")
            return
        self._request()

    def _answer(self, status, ctype, body, extra=()):
        if getattr(self, "command", None) == "HEAD":
            body = b""  # an answer to HEAD has no body, and says so
        lines = ["HTTP/1.1 %d %s" % (status, HTTPStatus(status).phrase),
                 "Content-Type: " + ctype,
                 "Content-Length: %d" % len(body),
                 "Connection: close"]
        lines.extend(extra)
        data = ("\r\n".join(lines) + "\r\n\r\n").encode("latin-1") + body
        self.wfile.write(data)
        self.wfile.flush()

    def _linger(self):
        """After an answer to a request we did not read: let the client finish sending."""
        try:
            self.connection.shutdown(socket.SHUT_WR)
            self.connection.settimeout(0.5)
            total = 0
            while total < (4 << 20):
                chunk = self.connection.recv(65536)
                if not chunk:
                    break
                total += len(chunk)
        except OSError:
            pass

    def _drain(self):
        left, cap = self._body_left, MAX_DRAIN
        while left > 0 and cap > 0:
            chunk = self.rfile.read(min(left, 65536))
            if not chunk:
                break
            left -= len(chunk)
            cap -= len(chunk)
        self._body_left = 0

    def _target(self):
        words = self.raw_requestline.decode("iso-8859-1").rstrip("\r\n").split()
        raw = words[1].encode("iso-8859-1").decode("utf-8", "replace")
        raw = raw.split("#", 1)[0]
        path, _, qs = raw.partition("?")
        return path, qs

    def _request(self):
        method = self.command
        status, ctype, body, extra = 200, "application/json; charset=utf-8", b"", ()
        try:
            result = self._process(method)
            if isinstance(result, Text):
                status, ctype = result.status, result.content_type
                body = result.text.encode("utf-8", "replace")
            else:
                status, obj = result
                body = _json_bytes(obj)
        except HttpError as exc:
            status, body, extra = exc.status, _json_bytes({"error": exc.message}), exc.headers
        except TallybookError as exc:
            status = _STATUS_OF_CODE.get(exc.code, 400)
            body = _json_bytes({"error": _message(exc)})
        except RecursionError:
            status, body = 400, _json_bytes({"error": "the request is nested too deeply"})
        except MemoryError:
            status, body = 500, _json_bytes({"error": "out of memory"})
        except Exception as exc:  # a bug must never print a traceback
            status = 500
            body = _json_bytes({"error": "internal error: %s" % type(exc).__name__})
        self._answer(status, ctype, body, extra)
        self._drain()

    def _process(self, method):
        path, qs = self._target()
        if not path.startswith("/"):
            raise HttpError(404, "no such path: %s" % path)
        pieces = [unquote(p, errors="replace") for p in path[1:].split("/")]
        routes = resolve(pieces)
        length_text = self.headers.get("Content-Length")
        declared = None
        if length_text is not None and _DIGITS.fullmatch(length_text) and length_text.isascii():
            declared = int(length_text)
            self._body_left = declared
        if routes is None:
            raise HttpError(404, "no such path: %s" % path)
        handler = routes.get(method)
        if handler is None:
            allow = ", ".join(sorted(routes))
            raise HttpError(405, "method %s is not allowed here; use %s" % (method, allow),
                            ["Allow: " + allow])
        # the body: length, then type
        if length_text is None:
            declared = 0
        if declared is None:
            raise HttpError(400, "Content-Length must be a whole number")
        if self.headers.get("Transfer-Encoding") is not None:
            raise HttpError(400, "Transfer-Encoding is not supported; send a Content-Length")
        if declared > MAX_BODY:
            raise HttpError(413, "the body is larger than %d bytes" % MAX_BODY)
        raw = self.rfile.read(declared) if declared else b""
        self._body_left = 0
        if len(raw) < declared:
            raise HttpError(400, "the body is shorter than its Content-Length")
        ctype = (self.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
        if method in ("POST", "PUT") and raw and ctype not in _accepted_types(pieces):
            raise HttpError(415, "unsupported Content-Type %r; use %s"
                            % (ctype, " or ".join(_accepted_types(pieces))))
        query = {}
        if qs:
            for name, value in parse_qsl(qs, keep_blank_values=True, errors="replace"):
                query[name] = value
        if method in ("GET", "DELETE"):
            raw = b""
        req = Request(self.server, method, pieces, query, raw, ctype)
        return handler(req)


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    block_on_close = False
    request_queue_size = 128

    def server_bind(self):
        socketserver.TCPServer.server_bind(self)
        host, port = self.server_address[:2]
        self.server_name = str(host)
        self.server_port = port

    def handle_error(self, request, client_address):
        pass  # a dropped connection or a bug in one request never reaches the terminal


class _Server6(_Server):
    address_family = socket.AF_INET6


# ---------------------------------------------------------------------------
# starting
# ---------------------------------------------------------------------------
def check_book(db_path):
    """Open the book once and check it as every command does."""
    with Store.open(db_path) as store:
        version = store.version
        if version < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % version)


def make_server(db_path, host="127.0.0.1", port=0, today=None):
    """A bound (not yet serving) server; ``serve_forever`` / ``shutdown`` / ``server_close`` as usual."""
    check_book(db_path)
    full = os.path.abspath(os.fspath(db_path))
    cls = _Server6 if ":" in host else _Server
    try:
        server = cls((host, port), Handler)
    except OverflowError:
        raise ValidationError("invalid port: %s" % (port,))
    except OSError as exc:
        raise ConflictError("cannot listen on %s:%s: %s" % (host, port, exc.strerror or exc))
    server.db_path = full
    server.today = today
    return server


def serve(db_path, host="127.0.0.1", port=0, today=None, *, _started=None):
    """Serve the book until SIGINT or SIGTERM; returns 0.

    ``_started(server)`` (for tests) is called once the listening line is printed.
    """
    server = make_server(db_path, host, port, today)
    previous = {}
    try:
        if threading.current_thread() is threading.main_thread():
            def stop(signum, frame):
                threading.Thread(target=server.shutdown, daemon=True).start()
            for sig in (signal.SIGINT, signal.SIGTERM):
                previous[sig] = signal.signal(sig, stop)
        shown = "[%s]" % host if ":" in host else host
        try:
            sys.stdout.write("tallybook listening on http://%s:%d\n" % (shown, server.server_address[1]))
            sys.stdout.flush()
        except (OSError, ValueError):
            pass
        if _started is not None:
            _started(server)
        try:
            server.serve_forever(poll_interval=0.1)
        except KeyboardInterrupt:
            pass
    finally:
        server.server_close()
        for sig, old in previous.items():
            signal.signal(sig, old)
    return 0
